using System.Text.Json;
using Infisical.Sdk;
using Infisical.Sdk.Model;

internal class Program
{

  public static string RandomString(int length)
  {
    return new string(Enumerable.Repeat("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789", length)
        .Select(s => s[Random.Shared.Next(s.Length)]).ToArray());
  }

  private static void Main(string[] args)
  {

    var machineIdentityClientId = Environment.GetEnvironmentVariable("INFISICAL_MACHINE_IDENTITY_CLIENT_ID");
    var machineIdentityClientSecret = [REDACTED]"INFISICAL_MACHINE_IDENTITY_CLIENT_SECRET");
    var projectId = Environment.GetEnvironmentVariable("INFISICAL_PROJECT_ID");


    if (string.IsNullOrEmpty(machineIdentityClientId) || string.IsNullOrEmpty(machineIdentityClientSecret) || string.IsNullOrEmpty(projectId))
    {

      Console.WriteLine("INFISICAL_MACHINE_IDENTITY_CLIENT_ID: " + machineIdentityClientId);
      Console.WriteLine("INFISICAL_MACHINE_IDENTITY_CLIENT_SECRET: " + machineIdentityClientSecret);
      Console.WriteLine("INFISICAL_PROJECT_ID: " + projectId);

      Console.WriteLine("INFISICAL_MACHINE_IDENTITY_CLIENT_ID, INFISICAL_MACHINE_IDENTITY_CLIENT_SECRET, and INFISICAL_PROJECT_ID must be set");
      return;
    }


    var settings = new InfisicalSdkSettingsBuilder()
      .WithHostUri("http://localhost:8080")
      .Build();


    var client = new InfisicalClient(settings);
    var _ = client.Auth().UniversalAuth().LoginAsync(machineIdentityClientId, machineIdentityClientSecret).Result;

    // sleep for 10 seconds
    Console.WriteLine("Sleeping for 5 seconds");
    Thread.Sleep(5000);

    Console.WriteLine("Done sleeping");

    var envVars = Environment.GetEnvironmentVariables();
    Console.WriteLine("\n\n\nEnvironment variables:");
    foreach (var envVar in envVars)
    {
      Console.WriteLine($"{envVar} {Environment.NewLine}");
    }

    var newSecretName = $".NET-SDK-TEST-{RandomString(32)}";

    var createSecretOptions = new CreateSecretOptions
    {
      SecretName = newSecretName,
      EnvironmentSlug = "dev",
      SecretPath = "/test",
      SecretValue = RandomString(10),
      ProjectId = projectId,
    };

    Console.WriteLine("\n\n\nCreate secret response:");
    Console.WriteLine(JsonSerializer.Serialize(client.Secrets().CreateAsync(createSecretOptions).Result, new JsonSerializerOptions { WriteIndented = true }));

    var options = new ListSecretsOptions
    {
      SetSecretsAsEnvironmentVariables = true,
      EnvironmentSlug = "dev",
      SecretPath = "/test",
      Recursive = true,
      // ExpandSecretReferences = true,
      ProjectId = projectId,
      // ViewSecretValue = true,
    };
    Console.WriteLine("\n\n\nList secrets response:");
    Console.WriteLine(JsonSerializer.Serialize(client.Secrets().ListAsync(options).Result, new JsonSerializerOptions { WriteIndented = true }));

    var getSecretOptions = new GetSecretOptions
    {
      SecretName = newSecretName,
      EnvironmentSlug = "dev",
      SecretPath = "/test",
      ProjectId = projectId,
    };
    Console.WriteLine("\n\n\nGet secret response:");
    Console.WriteLine(JsonSerializer.Serialize(client.Secrets().GetAsync(getSecretOptions).Result, new JsonSerializerOptions { WriteIndented = true }));


    // Close the Universal Auth client and create a new one with LDAP Auth
    Console.WriteLine("\n\n\n=== Switching to LDAP Auth ===");

    var ldapIdentityId = Environment.GetEnvironmentVariable("LDAP_IDENTITY_ID");
    var ldapUsername = Environment.GetEnvironmentVariable("LDAP_USERNAME");
    var ldapPassword = [REDACTED]"LDAP_PASSWORD");

    if (string.IsNullOrEmpty(ldapIdentityId) || string.IsNullOrEmpty(ldapUsername) || string.IsNullOrEmpty(ldapPassword))
    {
      Console.WriteLine("LDAP_IDENTITY_ID, LDAP_USERNAME, and LDAP_PASSWORD must be set to test LDAP auth");
      Console.WriteLine("Skipping LDAP auth test and continuing with Universal Auth client...");
    }
    else
    {
      // Create a new client with LDAP auth
      var ldapClient = new InfisicalClient(settings);
      try
      {
        Console.WriteLine("Authenticating with LDAP...");
        var ldapCredential = ldapClient.Auth().LdapAuth().LoginAsync(ldapIdentityId, ldapUsername, ldapPassword).Result;
        Console.WriteLine($"✅ LDAP Auth successful! Token: [REDACTED], Math.Min(20, ldapCredential.AccessToken.Length))}...");
        Console.WriteLine($"   Expires In: {ldapCredential.ExpiresIn} seconds");

        // Use the LDAP-authenticated client for remaining operations
        client = ldapClient;
      }
      catch (Exception ex)
      {
        Console.WriteLine($"❌ LDAP Auth failed: {ex.Message}");
        if (ex.InnerException != null)
        {
          Console.WriteLine($"   Inner Exception: {ex.InnerException.Message}");
        }
        Console.WriteLine("Continuing with Universal Auth client...");
      }
    }

    var updateSecretOptions = new UpdateSecretOptions
    {
      SecretName = newSecretName,
      EnvironmentSlug = "dev",
      SecretPath = "/test",
      NewSecretName = $"{newSecretName}-updated-name",
      NewSecretValue = $"{RandomString(10)}-updated-value",
      ProjectId = projectId,
    };

    Console.WriteLine("\n\n\nUpdate secret response:");
    Console.WriteLine(JsonSerializer.Serialize(client.Secrets().UpdateAsync(updateSecretOptions).Result, new JsonSerializerOptions { WriteIndented = true }));


    var deleteSecretOptions = new DeleteSecretOptions
    {
      SecretName = $"{newSecretName}-updated-name",
      EnvironmentSlug = "dev",
      SecretPath = "/test",
      ProjectId = projectId,
    };

    Console.WriteLine("\n\n\nDelete secret response:");
    Console.WriteLine(JsonSerializer.Serialize(client.Secrets().DeleteAsync(deleteSecretOptions).Result, new JsonSerializerOptions { WriteIndented = true }));
  }
}

using System;
using System.Threading;
using System.Threading.Tasks;
using Infisical.Sdk;
using Infisical.Sdk.Model;

namespace Infisical.Sdk.DeadlockTest
{
    // Custom SynchronizationContext that simulates WinForms behavior
    public class WinFormsSynchronizationContext : SynchronizationContext
    {
        private readonly Thread _mainThread;
        private readonly Queue<(SendOrPostCallback, object?)> _queue = new();
        private readonly object _lock = new();
        private volatile bool _running = true;

        public WinFormsSynchronizationContext()
        {
            _mainThread = Thread.CurrentThread;
        }

        public override void Post(SendOrPostCallback d, object? state)
        {
            lock (_lock)
            {
                _queue.Enqueue((d, state));
                Monitor.Pulse(_lock);
            }
        }

        public override void Send(SendOrPostCallback d, object? state)
        {
            if (Thread.CurrentThread == _mainThread)
            {
                d(state);
            }
            else
            {
                var executed = false;
                var exception = (Exception?)null;

                Post(_ =>
                {
                    try
                    {
                        d(state);
                    }
                    catch (Exception ex)
                    {
                        exception = ex;
                    }
                    finally
                    {
                        lock (_lock)
                        {
                            executed = true;
                            Monitor.Pulse(_lock);
                        }
                    }
                }, null);

                lock (_lock)
                {
                    while (!executed)
                        Monitor.Wait(_lock);
                }

                if (exception != null)
                    throw exception;
            }
        }

        public void ProcessMessages()
        {
            while (_running)
            {
                (SendOrPostCallback, object?) item;

                lock (_lock)
                {
                    while (_queue.Count == 0 && _running)
                        Monitor.Wait(_lock, 100);

                    if (!_running) break;
                    if (_queue.Count == 0) continue;

                    item = _queue.Dequeue();
                }

                try
                {
                    item.Item1(item.Item2);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Exception in message loop: {ex.Message}");
                }
            }
        }

        public void Stop()
        {
            lock (_lock)
            {
                _running = false;
                Monitor.PulseAll(_lock);
            }
        }
    }

    internal class Program
    {
        private static void Main(string[] args)
        {
            Console.WriteLine("=== Infisical SDK Deadlock Demonstration ===\n");

            // Test 1: Normal console app behavior (no deadlock)
            Console.WriteLine("1. Testing in normal console context...");
            TestNormalConsole();

            Console.WriteLine("\n" + new string('=', 50) + "\n");

            // Test 2: Simulated WinForms context (deadlock)
            Console.WriteLine("2. Testing in simulated WinForms context...");
            TestSimulatedWinForms();

            Console.WriteLine("\n" + new string('=', 50) + "\n");

            // Test 3: Proper async/await solution
            Console.WriteLine("3. Testing proper async/await solution...");
            TestAsyncAwaitSolution();

            Console.WriteLine("\n" + new string('=', 50) + "\n");

            // Test 4: Task.Run workaround
            Console.WriteLine("4. Testing Task.Run workaround...");
            TestTaskRunWorkaround();
        }

        private static void TestNormalConsole()
        {
            try
            {
                var settings = new InfisicalSdkSettingsBuilder()
                    .WithHostUri("https://app.infisical.com")
                    .Build();

                var client = new InfisicalClient(settings);

                Console.WriteLine("Using .Result in console app (works fine)...");
                var task = client.Auth().UniversalAuth().LoginAsync("fake-id", "fake-secret");

                // This works fine in console apps
                try
                {
                    var result = task.Result;
                    Console.WriteLine("✅ No deadlock occurred (but auth failed as expected)");
                }
                catch (AggregateException ex)
                {
                    Console.WriteLine($"✅ No deadlock - got expected auth error: {ex.InnerException?.Message}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"❌ Unexpected error: {ex.Message}");
            }
        }

        private static void TestSimulatedWinForms()
        {
            var winformsContext = new WinFormsSynchronizationContext();
            var deadlockDetected = false;
            var completed = false;
            Exception? caughtException = null;

            // This will run the actual test on the UI thread simulation
            var testCompletionSource = new TaskCompletionSource<bool>();

            // Post the deadlock test to run on the "UI thread"
            winformsContext.Post(_ =>
            {
                try
                {
                    // Set this thread's synchronization context
                    SynchronizationContext.SetSynchronizationContext(winformsContext);

                    var settings = new InfisicalSdkSettingsBuilder()
                        .WithHostUri("https://app.infisical.com")
                        .Build();

                    var client = new InfisicalClient(settings);

                    Console.WriteLine("Using .Result in WinForms-like context...");
                    Console.WriteLine("⏳ This should demonstrate a deadlock scenario...");

                    // This is the problematic pattern - calling .Result on the UI thread
                    // where the continuation needs to return to the same thread
                    var loginTask = client.Auth().UniversalAuth().LoginAsync("fake-id", "fake-secret");

                    // This should cause a deadlock if the SDK doesn't use ConfigureAwait(false)
                    try
                    {
                        var result = loginTask.Result;
                        completed = true;
                        Console.WriteLine("✅ Completed without deadlock (SDK properly uses ConfigureAwait(false))");
                    }
                    catch (AggregateException ex)
                    {
                        completed = true;
                        Console.WriteLine($"✅ Completed with expected auth error: {ex.InnerException?.Message}");
                        Console.WriteLine("   No deadlock occurred - SDK properly uses ConfigureAwait(false)");
                    }
                }
                catch (Exception ex)
                {
                    caughtException = ex;
                    Console.WriteLine($"❌ Unexpected error: {ex.Message}");
                }
                finally
                {
                    testCompletionSource.SetResult(true);
                }
            }, null);

            // Start the message pump and wait for the test to complete or timeout
            var messagePumpTask = Task.Run(() => winformsContext.ProcessMessages());

            // Wait for test completion or timeout (deadlock detection)
            var timeoutTask = Task.Delay(TimeSpan.FromSeconds(5));
            var completedTask = Task.WhenAny(testCompletionSource.Task, timeoutTask);

            if (completedTask.Result == timeoutTask)
            {
                deadlockDetected = true;
                Console.WriteLine("❌ DEADLOCK DETECTED - Test didn't complete within 5 seconds");
                Console.WriteLine("   This means the SDK is NOT using ConfigureAwait(false) properly");
                Console.WriteLine("   In a real WinForms app, the UI would freeze indefinitely");
            }

            // Clean up
            winformsContext.Stop();
            messagePumpTask.Wait(TimeSpan.FromSeconds(1));

            // Report final results
            if (deadlockDetected)
            {
                Console.WriteLine("\n🎯 TEST RESULT: DEADLOCK DETECTED!");
                Console.WriteLine("   ❌ The SDK needs ConfigureAwait(false) on all await calls");
                Console.WriteLine("   ❌ Using .Result in WinForms/WPF will freeze the UI");
            }
            else if (completed)
            {
                Console.WriteLine("\n✅ TEST RESULT: NO DEADLOCK DETECTED!");
                Console.WriteLine("   ✅ The SDK properly uses ConfigureAwait(false)");
                Console.WriteLine("   ✅ Using .Result in WinForms/WPF should be safe");
            }
            else if (caughtException != null)
            {
                Console.WriteLine($"\n❌ TEST RESULT: Test failed with exception: {caughtException.Message}");
            }
        }

        private static void TestAsyncAwaitSolution()
        {
            Task.Run(async () =>
            {
                try
                {
                    var settings = new InfisicalSdkSettingsBuilder()
                        .WithHostUri("https://app.infisical.com")
                        .Build();

                    var client = new InfisicalClient(settings);

                    Console.WriteLine("Using proper async/await pattern...");

                    try
                    {
                        var result = await client.Auth().UniversalAuth().LoginAsync("fake-id", "fake-secret");
                        Console.WriteLine("✅ Async/await completed successfully");
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"✅ Async/await completed with expected error: {ex.Message}");
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"❌ Unexpected error: {ex.Message}");
                }
            }).Wait();
        }

        private static void TestTaskRunWorkaround()
        {
            Task.Run(async () =>
            {
                try
                {
                    var settings = new InfisicalSdkSettingsBuilder()
                        .WithHostUri("https://app.infisical.com")
                        .Build();

                    var client = new InfisicalClient(settings);

                    Console.WriteLine("Using Task.Run workaround...");

                    try
                    {
                        await Task.Run(async () =>
                        {
                            var result = await client.Auth().UniversalAuth().LoginAsync("fake-id", "fake-secret");
                            return result;
                        });
                        Console.WriteLine("✅ Task.Run workaround completed successfully");
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"✅ Task.Run workaround completed with expected error: {ex.Message}");
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"❌ Unexpected error: {ex.Message}");
                }
            }).Wait();
        }
    }
}

using System.Threading.Tasks;
using Infisical.Sdk.Api;
using Infisical.Sdk.Client;
